# Generated by hsoliwal/com.synexia synexia-openrewrite-recipes/recipes/m3jdk21-legacy-recipe-custody-20261030/tools/
# repoint_importers.py (pattern IMPORTER_REPOINT_MECHANICAL). The legacy recipe paths that the custody receipt records
# as deleted are owned by hsoliwal/com.synexia at the seal commit below; this restores them, blob-verified, where an
# importer still reads them. No-op while the receipt is absent (legacy paths tracked) or no receipt path is missing.
#   restore.sh plan <root>              needed=true|false and the sparse patterns -> $GITHUB_OUTPUT (stdout outside CI)
#   restore.sh restore <root> <seal>    copy each missing path from the seal checkout, verify its Git blob id, add it
#                                       to the checkout's info/exclude, then remove the seal checkout
set -euo pipefail
SEAL=ac6518d9a38080c589b3b51cf1f18edeca1b9c41
RECEIPT=m3/release/legacy-recipe-custody-20261030.tsv
HEADER=$'schema\tpath\tblob\tsha256\tclass\tseal\tsynexia_path\tsynexia_blob\tsynexia_seal_commit\tdeletion_part'
US=$'\037'
mode=${1:?usage: restore.sh plan|restore <root> [seal-checkout]}
root=${2:?usage: restore.sh plan|restore <root> [seal-checkout]}
out=${GITHUB_OUTPUT:-/dev/stdout}
receipt=$root/$RECEIPT

# A row is missing when it is neither on disk nor tracked (a sparse checkout tracks paths it does not materialise).
# Rows use the unit separator, not tab: bash collapses runs of IFS whitespace and class (c) rows carry empty columns.
missing_rows() {
  # git ls-files has no --pathspec-from-file: pass the receipt paths as literal pathspecs through xargs instead.
  declare -A tracked=()
  if git -C "$root" rev-parse --git-dir > /dev/null 2>&1; then
    while IFS= read -r -d '' path; do tracked[$path]=1; done < <(awk -F '\t' 'NR > 1 {print $2}' "$receipt" |
      tr '\n' '\0' | xargs -0 -r git --literal-pathspecs -C "$root" ls-files -z --)
  fi
  awk -F '\t' -v OFS="$US" 'NR > 1 {print $2, $5, $7, $8, $9, $10}' "$receipt" |
  while IFS="$US" read -r path class spath sblob scommit part; do
    [ -e "$root/$path" ] || [ -n "${tracked[$path]:-}" ] && continue
    if [ -z "$spath" ] || [ "$scommit" != "$SEAL" ]; then
      echo "LEGACY_CUSTODY_REFUSED $path: class $class (deletion part $part) has no Synexia path at $SEAL" >&2
      exit 1
    fi
    printf '%s\n' "$path$US$spath$US$sblob"
  done
}

if [ ! -f "$receipt" ]; then
  if [ "$mode" = plan ]; then echo "needed=false" >> "$out"; fi
  echo "LEGACY_CUSTODY_RESTORE 0 (receipt absent: legacy paths are tracked)" >&2
  exit 0
fi
[ "$(head -n 1 "$receipt")" = "$HEADER" ] || { echo "LEGACY_CUSTODY_REFUSED receipt header drift" >&2; exit 1; }
rows=$(missing_rows)

if [ "$mode" = plan ]; then
  if [ -z "$rows" ]; then
    echo "needed=false" >> "$out"
    echo "LEGACY_CUSTODY_RESTORE 0 (every receipt path is present)" >&2
    exit 0
  fi
  # One pattern per distinct seal path: actions/checkout receives them as one environment variable, which Linux caps at
  # 131072 bytes (MAX_ARG_STRLEN); several receipt rows share a seal path. Refuse plainly before the runner fails with E2BIG.
  patterns=$(printf '%s\n' "$rows" | cut -d "$US" -f 2 | LC_ALL=C sort -u | sed 's#^#/#')
  bytes=$(printf '%s\n' "$patterns" | wc -c | tr -d ' ')
  [ "$bytes" -lt 130000 ] || { echo "LEGACY_CUSTODY_REFUSED sparse patterns are $bytes bytes, over the checkout input limit" >&2; exit 1; }
  { echo "needed=true"; echo "paths<<LEGACY_CUSTODY_PATHS"; printf '%s\n' "$patterns"; echo "LEGACY_CUSTODY_PATHS"; } >> "$out"
  echo "LEGACY_CUSTODY_PLAN $(printf '%s\n' "$rows" | grep -c .) patterns=$(printf '%s\n' "$patterns" | grep -c .) bytes=$bytes seal=$SEAL" >&2
  exit 0
fi

[ "$mode" = restore ] || { echo "unknown mode $mode" >&2; exit 2; }
syn=${3:?usage: restore.sh restore <root> <seal-checkout>}
[ "$(git -C "$syn" rev-parse HEAD)" = "$SEAL" ] || { echo "LEGACY_CUSTODY_REFUSED $syn is not $SEAL" >&2; exit 1; }
exclude=$(git -C "$root" rev-parse --path-format=absolute --git-path info/exclude 2>/dev/null || true)
if [ -n "$exclude" ]; then mkdir -p "$(dirname "$exclude")"; fi
n=0
while IFS="$US" read -r path spath sblob; do
  [ -n "$path" ] || continue
  [ -f "$syn/$spath" ] || { echo "LEGACY_CUSTODY_REFUSED seal checkout lacks $spath" >&2; exit 1; }
  mkdir -p "$(dirname "$root/$path")"
  cp "$syn/$spath" "$root/$path"
  got=$(git hash-object --no-filters "$root/$path")
  [ "$got" = "$sblob" ] || { echo "LEGACY_CUSTODY_REFUSED blob drift $path: $got != $sblob" >&2; exit 1; }
  if [ -n "$exclude" ]; then printf '/%s\n' "$path" >> "$exclude"; fi
  n=$((n + 1))
done <<< "$rows"
rm -rf "$syn"
echo "LEGACY_CUSTODY_RESTORED $n seal=$SEAL"
